export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds = {}
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  // Evaluate thresholds if provided
  const thresholdResults = [];
  let allThresholdsPassed = true;

  if (Object.keys(thresholds).length > 0) {
    for (const [metricId, minValue] of Object.entries(thresholds)) {
      const metric = evaluations.find((m) => m.id === metricId);
      if (!metric) {
        // This should not happen if validation is done in CLI, but handle gracefully
        continue;
      }
      const score = metric.score;
      const passed = score !== null && score >= minValue;
      if (!passed) {
        allThresholdsPassed = false;
      }
      thresholdResults.push({
        metric: metricId,
        label: metric.label,
        min: minValue,
        score: score,
        passed
      });
    }
  }

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  // Only add passed and thresholds fields if thresholds were evaluated
  if (Object.keys(thresholds).length > 0) {
    report.passed = allThresholdsPassed;
    report.thresholds = thresholdResults;
  }

  return report;
}

