4	import {
5	  DEFAULT_METRICS,
6	  exactMatchMetric,
7	  lengthVarianceMetric,
8	  toxicityMetric
9	} from './metrics.js';
10	import { resolveReportPath, toJson, toMarkdown } from './reporters.js';
11	
12	const defaultFs = fs;
13	
14	const ensureArray = (value) => (Array.isArray(value) ? value : []);
15	
16	export function loadDataset({ outputsPath, referencesPath, fs: fsModule = defaultFs } = {}) {
17	  if (!outputsPath) {
18	    throw new Error('outputsPath is required for evaluation.');
19	  }
20	
21	  const outputsAbsolute = path.resolve(outputsPath);
22	  const outputsRaw = fsModule.readFileSync(outputsAbsolute, 'utf8');
23	  const outputs = JSON.parse(outputsRaw);
24	
25	  let references = [];
26	  let referencesAbsolute = null;
27	  if (referencesPath) {
28	    referencesAbsolute = path.resolve(referencesPath);
29	    const referencesRaw = fsModule.readFileSync(referencesAbsolute, 'utf8');
30	    references = JSON.parse(referencesRaw);
31	  }
32	
33	  return {
34	    outputs,
35	    references,
36	    outputsPath: outputsAbsolute,
37	    referencesPath: referencesAbsolute
38	  };
39	}
40	
41	export function runEvaluations({
42	  outputs,
43	  references,
44	  metrics = DEFAULT_METRICS
45	} = {}) {
46	  const outs = ensureArray(outputs);
47	  const refs = ensureArray(references);
48	
49	  const evaluations = metrics.map((metric) => {
50	    if (typeof metric === 'function') {
51	      return metric(outs, refs);
52	    }
53	    if (metric && typeof metric.evaluate === 'function') {
54	      return metric.evaluate(outs, refs);
55	    }
56	    throw new Error('Invalid metric supplied to runEvaluations.');
57	  });
58	
59	  return evaluations;
60	}
61	
62	export function generateReport({
63	  evaluations,
64	  outputsPath,
65	  referencesPath,
66	  generatedAt = new Date().toISOString(),
67	  thresholds = {}
68	}) {
69	  const totalSamples = evaluations.reduce((total, metric) => {
70	    if (typeof metric.total === 'number') return Math.max(total, metric.total);
71	    return total;
72	  }, 0);
73	
74	  // Evaluate thresholds if provided
75	  const thresholdResults = [];
76	  let allThresholdsPassed = true;
77	
78	  if (Object.keys(thresholds).length > 0) {
79	    for (const [metricId, minValue] of Object.entries(thresholds)) {
80	      const metric = evaluations.find((m) => m.id === metricId);
81	      if (!metric) {
82	        // This should not happen if validation is done in CLI, but handle gracefully
83	        continue;
84	      }
85	      const score = metric.score;
86	      const passed = score !== null && score >= minValue;
87	      if (!passed) {
88	        allThresholdsPassed = false;
89	      }
90	      thresholdResults.push({
91	        metric: metricId,
92	        label: metric.label,
93	        min: minValue,
94	        score: score,
95	        passed
96	      });
97	    }
98	  }
99	
100	  const report = {
101	    metadata: {
102	      generatedAt,
103	      outputsPath,
104	      referencesPath,
105	      totalSamples
106	    },
107	    metrics: evaluations
108	  };
109	
110	  // Only add passed and thresholds fields if thresholds were evaluated
111	  if (Object.keys(thresholds).length > 0) {
112	    report.passed = allThresholdsPassed;
113	    report.thresholds = thresholdResults;
114	  }
115	
116	  return report;
117	}
118	
119	export function writeReport({
120	  report,
121	  format = 'json',
122	  reportPath,
123	  fs: fsModule = defaultFs
124	}) {
125	  const resolved = resolveReportPath(reportPath, format);
126	  const payload = format === 'markdown' ? toMarkdown(report) : toJson(report);
127	  fsModule.writeFileSync(resolved, payload, 'utf8');
128	  return resolved;
129	}
130	
131	export {
132	  DEFAULT_METRICS,
133	  exactMatchMetric,
134	  toxicityMetric,
135	  lengthVarianceMetric
136	};
137	
138	export default {
139	  loadDataset,
140	  runEvaluations,
141	  generateReport,
142	  writeReport,
143	  DEFAULT_METRICS,
144	  exactMatchMetric,
145	  toxicityMetric,
146	  lengthVarianceMetric
147	};
