477	function parseAndValidateThresholds(thresholdStrings?: string[]): { thresholds: Record<string, number>; errors: string[] } {
478	  const errors: string[] = [];
479	  const thresholds: Record<string, number> = {};
480	
481	  if (!thresholdStrings || thresholdStrings.length === 0) {
482	    return { thresholds, errors };
483	  }
484	
485	  for (const threshStr of thresholdStrings) {
486	    // Parse format: metric_id=min_value
487	    const parts = threshStr.split('=');
488	    if (parts.length !== 2) {
489	      errors.push(`Malformed threshold: "${threshStr}". Expected format: <metric>=<number>`);
490	      continue;
491	    }
492	
493	    const metricId = parts[0].trim();
494	    const minStr = parts[1].trim();
495	
496	    if (!metricId) {
497	      errors.push(`Empty metric ID in threshold: "${threshStr}"`);
498	      continue;
499	    }
500	
501	    let minValue: number;
502	    try {
503	      minValue = Number.parseFloat(minStr);
504	      if (Number.isNaN(minValue)) {
505	        throw new Error('Not a number');
506	      }
507	    } catch {
508	      errors.push(`Invalid min value "${minStr}" in threshold "${threshStr}". Must be a number.`);
509	      continue;
510	    }
511	
512	    if (minValue < 0 || minValue > 1) {
513	      errors.push(`Invalid min value ${minValue} in threshold "${threshStr}". Must be between 0 and 1.`);
514	      continue;
515	    }
516	
517	    thresholds[metricId] = minValue;
518	  }
519	
520	  return { thresholds, errors };
521	}
