58	export function resolveReportPath(reportPath, format = 'json') {
59	  if (!reportPath) {
60	    return format === 'markdown' ? path.resolve('frai-eval-report.md') : path.resolve('frai-eval-report.json');
61	  }
62	  const ext = path.extname(reportPath);
63	  if (!ext) {
64	    return format === 'markdown' ? `${reportPath}.md` : `${reportPath}.json`;
65	  }
66	  return reportPath;
67	}
