62	export function generateReport({
63	  evaluations,
64	  outputsPath,
65	  referencesPath,
66	  generatedAt = new Date().toISOString(),
67	  thresholds = {}
68	}) {
69	  const totalSamples = evaluations.reduce((total, metric) => {
70	    if (typeof metric.total === 'number') return Math.max(total, metric.total);
71	    return total;
72	  }, 0);
73	
74	  // Evaluate thresholds if provided
75	  const thresholdResults = [];
76	  let allThresholdsPassed = true;
77	
78	  if (Object.keys(thresholds).length > 0) {
79	    for (const [metricId, minValue] of Object.entries(thresholds)) {
80	      const metric = evaluations.find((m) => m.id === metricId);
81	      if (!metric) {
82	        // This should not happen if validation is done in CLI, but handle gracefully
83	        continue;
84	      }
85	      const score = metric.score;
86	      const passed = score !== null && score >= minValue;
87	      if (!passed) {
88	        allThresholdsPassed = false;
89	      }
90	      thresholdResults.push({
91	        metric: metricId,
92	        label: metric.label,
93	        min: minValue,
94	        score: score,
95	        passed
96	      });
97	    }
98	  }
99	
100	  const report = {
101	    metadata: {
102	      generatedAt,
103	      outputsPath,
104	      referencesPath,
105	      totalSamples
106	    },
107	    metrics: evaluations
108	  };
109	
110	  // Only add passed and thresholds fields if thresholds were evaluated
111	  if (Object.keys(thresholds).length > 0) {
112	    report.passed = allThresholdsPassed;
113	    report.thresholds = thresholdResults;
114	  }
115	
116	  return report;
117	}
