123	  fs: fsModule = defaultFs
124	}) {
125	  const resolved = resolveReportPath(reportPath, format);
126	  const payload = format === 'markdown' ? toMarkdown(report) : toJson(report);
127	  fsModule.writeFileSync(resolved, payload, 'utf8');
128	  return resolved;
129	}
