6	function parseAndValidateThresholds(thresholdStrings?: string[]): { thresholds: Record<string, number>; errors: string[] } {
7	  const errors: string[] = [];
8	  const thresholds: Record<string, number> = {};
9	
10	  if (!thresholdStrings || thresholdStrings.length === 0) {
11	    return { thresholds, errors };
12	  }
13	
14	  for (const threshStr of thresholdStrings) {
15	    // Parse format: metric_id=min_value
16	    const parts = threshStr.split('=');
17	    if (parts.length !== 2) {
18	      errors.push(`Malformed threshold: "${threshStr}". Expected format: <metric>=<number>`);
19	      continue;
20	    }
21	
22	    const metricId = parts[0].trim();
23	    const minStr = parts[1].trim();
24	
25	    if (!metricId) {
26	      errors.push(`Empty metric ID in threshold: "${threshStr}"`);
27	      continue;
28	    }
29	
30	    let minValue: number;
31	    try {
32	      minValue = Number.parseFloat(minStr);
33	      if (Number.isNaN(minValue)) {
34	        throw new Error('Not a number');
35	      }
36	    } catch {
37	      errors.push(`Invalid min value "${minStr}" in threshold "${threshStr}". Must be a number.`);
38	      continue;
39	    }
40	
41	    if (minValue < 0 || minValue > 1) {
42	      errors.push(`Invalid min value ${minValue} in threshold "${threshStr}". Must be between 0 and 1.`);
43	      continue;
44	    }
45	
46	    thresholds[metricId] = minValue;
47	  }
48	
49	  return { thresholds, errors };
50	}
