    const validIds = ['exact_match', 'toxicity', 'length_variance'];
    console.error(`\nValid metric IDs: ${validIds.join(', ')}`);
    process.exit(2);
  }

  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });

  // Validate that all threshold metrics exist
  const validationErrors = validateThresholdMetrics(thresholds, evaluations);
  if (validationErrors.length > 0) {
    log.error('Threshold validation failed:');
    validationErrors.forEach((err) => console.error(`  - ${err}`));
    process.exit(2);
  }

  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds: Object.keys(thresholds).length > 0 ? thresholds : undefined
  });
  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  // Handle threshold exit codes
  if (Object.keys(thresholds).length > 0) {
    if (report.passed) {
      process.exit(0);
    } else {
      process.exit(1);
    }
  }
}

  // Evaluate thresholds if provided
  const thresholdResults = [];
  let allThresholdsPassed = true;

  if (Object.keys(thresholds).length > 0) {
    for (const [metricId, minValue] of Object.entries(thresholds)) {
      const metric = evaluations.find((m) => m.id === metricId);
      if (!metric) {
        // This should not happen if validation is done in CLI, but handle gracefully
        continue;
      }
      const score = metric.score;
      const passed = score !== null && score >= minValue;
      if (!passed) {
        allThresholdsPassed = false;
      }
      thresholdResults.push({
        metric: metricId,
        label: metric.label,
        min: minValue,
        score: score,
        passed
      });
