546	function runEvalCommand(options: EvalOptions) {
547	  assertFileExists(options.outputs);
548	
549	  // Parse and validate thresholds first (before any report generation)
550	  const { thresholds, errors: parseErrors } = parseAndValidateThresholds(options.threshold);
551	  if (parseErrors.length > 0) {
552	    log.error('Invalid threshold arguments:');
553	    parseErrors.forEach((err) => console.error(`  - ${err}`));
554	    const validIds = ['exact_match', 'toxicity', 'length_variance'];
555	    console.error(`\nValid metric IDs: ${validIds.join(', ')}`);
556	    process.exit(2);
557	  }
558	
559	  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
560	    outputsPath: options.outputs,
561	    referencesPath: options.references
562	  });
563	  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
564	    outputs: dataset.outputs,
565	    references: dataset.references
566	  });
567	
568	  // Validate that all threshold metrics exist
569	  const validationErrors = validateThresholdMetrics(thresholds, evaluations);
570	  if (validationErrors.length > 0) {
571	    log.error('Threshold validation failed:');
572	    validationErrors.forEach((err) => console.error(`  - ${err}`));
573	    process.exit(2);
574	  }
575	
576	  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
577	    evaluations,
578	    outputsPath: dataset.outputsPath,
579	    referencesPath: dataset.referencesPath,
580	    thresholds: Object.keys(thresholds).length > 0 ? thresholds : undefined
581	  });
582	  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
583	    report,
584	    format: options.format ?? 'json',
585	    reportPath: options.report
586	  });
587	  log.success('Evaluation report generated.', { path: resolvedPath });
588	
589	  // Handle threshold exit codes
590	  if (Object.keys(thresholds).length > 0) {
591	    if (report.passed) {
592	      process.exit(0);
593	    } else {
594	      process.exit(1);
595	    }
596	  }
597	}
